type event struct {
	ID string `json:"id"`
}

func consume(r *kafka.Reader, seen map[string]struct{}) {
	ctx := context.Background()
	for {
		m, err := r.FetchMessage(ctx) // FetchMessage does NOT auto-commit
		if err != nil {
			log.Fatal(err)
		}
		var e event
		json.Unmarshal(m.Value, &e)

		if _, dup := seen[e.ID]; !dup { // idempotency guard
			seen[e.ID] = struct{}{}
			log.Printf("processed %s (off=%d)", e.ID, m.Offset)
		}
		_ = r.CommitMessages(ctx, m) // commit AFTER processing
	}
}
